52	// File-scope flags set by DiscreteMaskAccessConversionPass::runOnOperation()
53	// before pattern application, so that OpRewritePattern subclasses can read
54	// them.
55	static bool compileOn91095Flag = false;
56	static bool forceSimtTemplateFlag = false;
57	static bool enableSyncBlockLockFlag = true;
58	static constexpr const char *routeDiscreteMaskToSimtAttrName =
59	    "route_discrete_mask_to_simt";
60	
61	static bool traceUserToTargetOp(Value val) {
62	  llvm::SmallVector<Value, 32> worklist;
63	  llvm::SmallPtrSet<Value, 32> visited;
64	  worklist.push_back(val);
65	
66	  while (!worklist.empty()) {
67	    Value currVal = worklist.pop_back_val();
68	    if (!visited.insert(currVal).second)
69	      continue;
70	
71	    for (Operation *user : currVal.getUsers()) {
72	      if (auto mulOp = dyn_cast<arith::MulIOp>(user)) {
73	        Value lhs = mulOp.getLhs();
74	        Value rhs = mulOp.getRhs();
75	        Value constVal;
76	        if (lhs.getDefiningOp<arith::ConstantOp>()) {
77	          constVal = lhs;
78	        } else if (rhs.getDefiningOp<arith::ConstantOp>()) {
79	          constVal = rhs;
80	        } else {
81	          continue;
82	        }
83	
84	        auto constDef = constVal.getDefiningOp<arith::ConstantOp>();
85	        int64_t blockSize = 0;
86	        if (auto intAttr = mlir::dyn_cast<IntegerAttr>(constDef.getValue())) {
87	          blockSize = intAttr.getInt();
88	        }
89	
90	        llvm::SmallVector<Value, 8> searchQueue;
91	        llvm::SmallPtrSet<Value, 8> searchVis;
92	        for (Value mulRes : mulOp->getResults()) {
93	          searchQueue.push_back(mulRes);
94	          searchVis.insert(mulRes);
95	        }
96	
97	        bool findMatch = false;
98	        while (!searchQueue.empty()) {
99	          Value checkVal = searchQueue.pop_back_val();
100	          for (Operation *subUser : checkVal.getUsers()) {
101	            if (auto addOp = dyn_cast<arith::AddIOp>(subUser)) {
102	              Value otherOperand = (addOp.getLhs() == checkVal)
103	                                       ? addOp.getRhs()
104	                                       : addOp.getLhs();
105	
106	              Value curSrc = otherOperand;
107	              bool hitRange = false;
108	              int depth = 0;
109	              while (curSrc.getDefiningOp() && depth < 5) {
110	                Operation *defOp = curSrc.getDefiningOp();
111	                if (auto rangeOp = dyn_cast<triton::MakeRangeOp>(defOp)) {
112	                  if (rangeOp.getEnd() == blockSize) {
113	                    hitRange = true;
114	                    break;
115	                  }
116	                }
117	
118	                if (isa<arith::ExtSIOp, triton::SplatOp, triton::ExpandDimsOp,
119	                        triton::BroadcastOp>(defOp)) {
120	                  curSrc = defOp->getOperand(0);
121	                  depth++;
122	                  continue;
123	                }
124	                break;
125	              }
126	              if (hitRange) {
127	                findMatch = true;
128	                break;
129	              }
130	            }
131	            if (isa<arith::ExtSIOp, triton::SplatOp, triton::ExpandDimsOp,
132	                    triton::BroadcastOp>(subUser)) {
133	              for (Value subRes : subUser->getResults()) {
134	                if (!searchVis.count(subRes)) {
135	                  searchVis.insert(subRes);
136	                  searchQueue.push_back(subRes);
137	                }
138	              }
139	            }
140	          }
141	          if (findMatch)
142	            break;
143	        }
144	        if (findMatch) {
145	          return true;
146	        }
147	
148	        for (Value mulRes : mulOp->getResults()) {
149	          worklist.push_back(mulRes);
150	        }
151	      }
152	
153	      if (isa<arith::ExtSIOp, triton::SplatOp, triton::ExpandDimsOp,
154	              triton::BroadcastOp>(user)) {
155	        for (Value res : user->getResults()) {
156	          worklist.push_back(res);
157	        }
158	      }
159	    }
160	  }
161	  return false;
162	}
