164	static bool checkAllProgramIdNonOverlap(ModuleOp module) {
165	  bool allNonOverlap = true;
166	  module.walk([&](triton::GetProgramIdOp pidOp) {
167	    if (!traceUserToTargetOp(pidOp.getResult())) {
168	      allNonOverlap = false;
169	    }
170	  });
171	  return allNonOverlap;
172	}
173	
174	LogicalResult isDiscreteMask(Operation *op, Value mask,
175	                             PatternRewriter &rewriter) {
176	  if (!mask || op->hasAttr(routeDiscreteMaskToSimtAttrName)) {
177	    return failure();
178	  }
179	
180	  MaskState mstate;
181	  auto isContMask = mstate.parse(mask, op->getLoc(), rewriter);
182	  if (!isContMask.failed()) {
183	    mstate.eraseInsertedOps(op, rewriter);
184	    return failure();
185	  }
186	  return success();
187	}
188	
189	// Recursively collect all leaf operands of a nested arith::AndIOp tree.
190	// This function also normalizes masks by distributing broadcast over andi
191	//   broadcast(andi(a, b)) = andi(broadcast(a), broadcast(b))
192	// so that inner AND operands nested inside a broadcast are still reachable.
193	static void collectAndLeaves(Value mask, SmallVectorImpl<Value> &leaves,
194	                             Location loc, PatternRewriter &rewriter) {
195	  if (auto andOp = mask.getDefiningOp<arith::AndIOp>()) {
196	    collectAndLeaves(andOp.getLhs(), leaves, loc, rewriter);
197	    collectAndLeaves(andOp.getRhs(), leaves, loc, rewriter);
198	  } else if (auto broadcastOp = mask.getDefiningOp<triton::BroadcastOp>()) {
199	    // Distribute broadcast over andi so we can inspect each factor separately.
200	    if (auto innerAnd = broadcastOp.getSrc().getDefiningOp<arith::AndIOp>()) {
201	      Type dstType = mask.getType();
202	      Value broadcastA =
203	          rewriter.create<triton::BroadcastOp>(loc, dstType, innerAnd.getLhs())
204	              .getResult();
205	      Value broadcastB =
206	          rewriter.create<triton::BroadcastOp>(loc, dstType, innerAnd.getRhs())
207	              .getResult();
208	      collectAndLeaves(broadcastA, leaves, loc, rewriter);
209	      collectAndLeaves(broadcastB, leaves, loc, rewriter);
210	    } else {
211	      leaves.push_back(mask);
212	    }
213	  } else {
214	    leaves.push_back(mask);
215	  }
216	}
217	
218	struct MaskDecomposition {
219	  // AND of all leaves that MaskState::parse() can analyze as a rectangle mask.
220	  // nullptr when no such leaves exist.
221	  Value contMask;
222	  // AND of all leaves that MaskState::parse() cannot analyze
223	  // (discrete/runtime). nullptr when no such leaves exist.
224	  Value discMask;
225	};
226	
227	// Decompose an AND-tree mask into its continuous and discrete leaf components
228	// so that we can use contMask to bound GM accesses while discMask still drives
229	// the per-element selection.
230	static MaskDecomposition decomposeAndMask(Operation *op, Value mask,
231	                                          const Location &loc,
232	                                          PatternRewriter &rewriter) {
233	  SmallVector<Value> leaves;
234	  collectAndLeaves(mask, leaves, loc, rewriter);
235	
236	  SmallVector<Value> contLeaves;
237	  SmallVector<Value> discLeaves;
238	
239	  for (Value leaf : leaves) {
240	    MaskState st;
241	    if (st.parse(leaf, loc, rewriter).succeeded()) {
242	      if (st.isMask())
243	        contLeaves.push_back(leaf);
244	      else
245	        discLeaves.push_back(leaf);
246	    } else {
247	      discLeaves.push_back(leaf);
248	    }
249	  }
250	
251	  Value contMask = nullptr;
252	  for (Value v : contLeaves)
253	    contMask =
254	        contMask ? rewriter.create<arith::AndIOp>(loc, contMask, v).getResult()
255	                 : v;
256	
257	  Value discMask = nullptr;
258	  for (Value v : discLeaves)
259	    discMask =
260	        discMask ? rewriter.create<arith::AndIOp>(loc, discMask, v).getResult()
261	                 : v;
262	
263	  return {contMask, discMask};
264	}
