266	struct DiscreteMaskStoreConversion : OpRewritePattern<triton::StoreOp> {
267	  using OpRewritePattern<triton::StoreOp>::OpRewritePattern;
268	
269	  LogicalResult matchAndRewrite(triton::StoreOp op,
270	                                PatternRewriter &rewriter) const final {
271	    auto mask = op.getMask();
272	    auto loc = op.getLoc();
273	    auto dst = op.getPtr();
274	    auto src = op.getValue();
275	
276	    if (failed(isDiscreteMask(op, mask, rewriter)))
277	      return failure();
278	
279	    auto ptr = op.getPtr();
280	    auto ptrType = dyn_cast<RankedTensorType>(ptr.getType());
281	    bool rankWithinIndirectFastPathLimit =
282	        ptrType && ptrType.getShape().size() <= 5;
283	    if (compileOn91095Flag && forceSimtTemplateFlag &&
284	        rankWithinIndirectFastPathLimit) {
285	      op->setAttr(routeDiscreteMaskToSimtAttrName, rewriter.getUnitAttr());
286	      return failure();
287	    }
288	
289	    // When mask = contMask & discMask, use contMask to bound GM accesses and
290	    // discMask to select the final per-element value. This prevents the
291	    // unguarded full-load from reading past the tail-block boundary.
292	    auto [contMask, discMask] = decomposeAndMask(op, mask, loc, rewriter);
293	    if (contMask && discMask) {
294	      // insert sync_block_lock
295	      auto lockVar = MemOpConverter::createSyncBlockLockVar(rewriter, loc);
296	      if (enableSyncBlockLockFlag) {
297	        rewriter.create<hivm::SyncBlockLockOp>(loc, lockVar);
298	      }
299	      auto safeLoad = rewriter.create<triton::LoadOp>(
300	          loc, dst, contMask, op.getCache(), op.getEvict(), false);
301	      auto selOp = rewriter.create<arith::SelectOp>(loc, discMask, src,
302	                                                    safeLoad.getResult());
303	      auto newStore = rewriter.create<triton::StoreOp>(
304	          loc, dst, selOp, contMask, op.getCache(), op.getEvict());
305	      newStore->setAttr(ConverterUtils::discreteMaskAttrName,
306	                        UnitAttr::get(rewriter.getContext()));
307	      if (enableSyncBlockLockFlag) {
308	        rewriter.create<hivm::SyncBlockUnlockOp>(loc, lockVar);
309	      }
310	      rewriter.replaceOp(op, newStore);
311	      return success();
312	    }
313	
314	    // SIMD fallback: original full load + select (contMask absent, pure
315	    // discrete). Has DDR OOB risk but no better option in pure simd mode.
316	    // insert sync_block_lock to serialize the read-modify-write window.
317	    auto lockVar = MemOpConverter::createSyncBlockLockVar(rewriter, loc);
318	    if (enableSyncBlockLockFlag) {
319	      rewriter.create<hivm::SyncBlockLockOp>(loc, lockVar);
320	    }
321	    auto loadFromDstOp = rewriter.create<triton::LoadOp>(
322	        loc, dst, op.getCache(), op.getEvict(), false);
323	    auto selOp = rewriter.create<arith::SelectOp>(loc, mask, src,
324	                                                  loadFromDstOp.getResult());
325	    auto newStore = rewriter.create<triton::StoreOp>(
326	        loc, dst, selOp, op.getCache(), op.getEvict());
327	    newStore->setAttr(ConverterUtils::discreteMaskAttrName,
328	                      UnitAttr::get(rewriter.getContext()));
329	    if (enableSyncBlockLockFlag) {
330	      rewriter.create<hivm::SyncBlockUnlockOp>(loc, lockVar);
331	    }
332	    rewriter.replaceOp(op, newStore);
333	    return success();
334	  }
335	};
336	
337	struct DiscreteMaskLoadConversion : OpRewritePattern<triton::LoadOp> {
338	  using OpRewritePattern<triton::LoadOp>::OpRewritePattern;
339	
340	  LogicalResult matchAndRewrite(triton::LoadOp op,
341	                                PatternRewriter &rewriter) const final {
342	    auto loc = op.getLoc();
343	    auto other = op.getOther();
344	    auto mask = op.getMask();
345	    auto ptr = op.getPtr();
346	
347	    if (failed(isDiscreteMask(op, mask, rewriter)))
348	      return failure();
349	
350	    auto ptrType = dyn_cast<RankedTensorType>(ptr.getType());
351	    bool rankWithinIndirectFastPathLimit =
352	        ptrType && ptrType.getShape().size() <= 5;
353	    if (compileOn91095Flag && forceSimtTemplateFlag &&
354	        rankWithinIndirectFastPathLimit) {
355	      op->setAttr(routeDiscreteMaskToSimtAttrName, rewriter.getUnitAttr());
356	      return failure();
357	    }
358	
359	    // SIMD path: when mask = contMask & discMask, load only the safe range
360	    // defined by contMask and use discMask for the per-element select,
361	    // avoiding OOB reads.
362	    auto [contMask, discMask] = decomposeAndMask(op, mask, loc, rewriter);
363	    if (contMask && discMask) {
364	      if (!other) {
365	        FailureOr<Value> constant = specializeTypelessValueToConstant(
366	            TypelessValue::Zero, ptr.getType(), loc, rewriter);
367	        if (failed(constant)) {
368	          llvm_unreachable("Unsupported type for constant creation");
369	        }
370	        other = *constant;
371	      }
372	      auto safeLoad = rewriter.create<triton::LoadOp>(
373	          loc, ptr, contMask, op.getCache(), op.getEvict(), op.getIsVolatile());
374	      // Use combined mask to select the result, avoid the uninitialized memory
375	      // access.
376	      auto combinedMask =
377	          rewriter.create<arith::AndIOp>(loc, contMask, discMask);
378	      auto discreteMaskOp = rewriter.create<arith::SelectOp>(
379	          loc, combinedMask, safeLoad.getResult(), other);
380	      rewriter.replaceOp(op, discreteMaskOp);
381	      return success();
382	    }
383	
384	    if (!other) {
385	      FailureOr<Value> constant = specializeTypelessValueToConstant(
386	          TypelessValue::Zero, ptr.getType(), loc, rewriter);
387	      if (failed(constant))
388	        llvm_unreachable("Unsupported type for constant creation");
389	      other = *constant;
390	    }
391	
392	    auto newLoadOp = rewriter.create<triton::LoadOp>(
393	        loc, ptr, op.getCache(), op.getEvict(), op.getIsVolatile());
394	    auto discreteMaskOp =
395	        rewriter.create<arith::SelectOp>(loc, mask, newLoadOp, other);
396	    rewriter.replaceOp(op, discreteMaskOp);
397	    return success();
398	  }
399	};
