401	struct DiscreteMaskAtomicConversion
402	    : OpRewritePattern<mlir::triton::AtomicRMWOp> {
403	  using OpRewritePattern<mlir::triton::AtomicRMWOp>::OpRewritePattern;
404	
405	  LogicalResult matchAndRewrite(mlir::triton::AtomicRMWOp op,
406	                                PatternRewriter &rewriter) const final {
407	    auto loc = op.getLoc();
408	    auto ptr = op.getPtr();
409	    auto src = op.getVal();
410	    auto mask = op.getMask();
411	    RMWOp rmwOp = op.getAtomicRmwOp();
412	
413	    if (failed(isDiscreteMask(op, mask, rewriter)))
414	      return failure();
415	
416	    const std::map<RMWOp, TypelessValue> initMap = {
417	        {RMWOp::FADD, TypelessValue::Zero},
418	        {RMWOp::ADD, TypelessValue::Zero},
419	        {RMWOp::UMAX, TypelessValue::Zero},
420	        {RMWOp::OR, TypelessValue::Zero},
421	        {RMWOp::MIN, TypelessValue::Max},
422	        {RMWOp::UMIN, TypelessValue::Max},
423	        {RMWOp::AND, TypelessValue::Max},
424	        {RMWOp::MAX, TypelessValue::Min},
425	        {RMWOp::XOR, TypelessValue::Zero},
426	        {RMWOp::XCHG, TypelessValue::Undefined},
427	    };
428	    assert(initMap.find(rmwOp) != initMap.end());
429	    auto typelessVal = initMap.at(rmwOp);
430	    if (typelessVal == TypelessValue::Undefined) {
431	      // Undefined default value atomic op will be decomposed in AscendNPU-IR
432	      op->setAttr(ConverterUtils::discreteMaskAttrName,
433	                  UnitAttr::get(rewriter.getContext()));
434	      return failure();
435	    }
436	
437	    FailureOr<mlir::Value> fill = specializeTypelessValueToConstant(
438	        typelessVal, src.getType(), loc, rewriter);
439	    if (failed(fill)) {
440	      LLVM_DEBUG({
441	        llvm::dbgs() << "Unsupported type for constant creation: "
442	                     << src.getType() << "\n";
443	      });
444	      op->emitError("Unsupported atomic operation.");
445	      return failure();
446	    }
447	
448	    auto maskedValue = rewriter.create<arith::SelectOp>(loc, mask, src, *fill);
449	    auto newAtomicOp = rewriter.create<mlir::triton::AtomicRMWOp>(
450	        loc, src.getType(), rmwOp, ptr, maskedValue, mlir::Value(), op.getSem(),
451	        op.getScope());
452	    rewriter.replaceOp(op, newAtomicOp);
453	    return success();
454	  }
455	};
456	
457	DiscreteMaskAccessConversionPass::DiscreteMaskAccessConversionPass(
458	    const DiscreteMaskAccessConversionOptions &options)
459	    : DiscreteMaskAccessConversionBase(options) {}
460	
461	void DiscreteMaskAccessConversionPass::runOnOperation() {
462	  compileOn91095Flag = this->compileOn91095;
463	  forceSimtTemplateFlag = this->forceSimtTemplate;
464	  bool tileNonOverlap = checkAllProgramIdNonOverlap(getOperation());
465	  enableSyncBlockLockFlag = !tileNonOverlap;
466	  auto moduleOp = getOperation();
467	
468	  RewritePatternSet patterns(&getContext());
469	  patterns.add<DiscreteMaskLoadConversion, DiscreteMaskStoreConversion,
470	               DiscreteMaskAtomicConversion>(patterns.getContext());
471	  if (failed(applyPatternsGreedily(moduleOp, std::move(patterns)))) {
472	    moduleOp->emitError("failed to apply discrete mask access patterns");
473	    signalPassFailure();
474	  }
475	
476	  // Clean up dead analysis ops left behind by MaskState::parse().
477	  // These are trivially-dead auxiliary ops (constants, arithmetic) with no
478	  // users that parse() creates as side effects of mask analysis.
479	  PassManager pm(&getContext(), moduleOp.getOperationName());
480	  pm.addPass(createCSEPass());
481	  pm.addPass(createCanonicalizerPass());
482	  if (failed(runPipeline(pm, getOperation()))) {
483	    moduleOp->emitWarning(
484	        "DiscreteMaskAccessConversion: dead-code cleanup failed");
485	  }
486	
487	  LLVM_DEBUG({
488	    llvm::dbgs() << "==============================================\n";
489	    llvm::dbgs() << "After DiscreteMaskAccessConversionPass:\n" << moduleOp;
490	    llvm::dbgs() << "\n==============================================\n";
491	  });
492	}
493	
494	void DiscreteMaskAccessConversionPass::getDependentDialects(
495	    DialectRegistry &registry) const {
496	  registry
497	      .insert<arith::ArithDialect, triton::TritonDialect, hivm::HIVMDialect>();
498	}
499	
500	std::unique_ptr<OperationPass<ModuleOp>>
501	mlir::triton::createDiscreteMaskAccessConversionPass(
502	    const DiscreteMaskAccessConversionOptions &options) {
503	  return std::make_unique<DiscreteMaskAccessConversionPass>(options);
504	}
