179	    rewriter.setInsertionPointToStart(forOp.getBody());
180	    loops.push_back(forOp);
181	    ivs.push_back(forOp.getInductionVar());
182	  }
183	
184	  bodyFunc(ivs);
185	
186	  if (!loops.empty()) {
187	    rewriter.setInsertionPointAfter(loops.front());
188	  }
